WITH session_stats AS (SELECT session_id, MAX(duration_sec) AS max_duration_sec, COUNT(duration_sec) AS duration_sec_count FROM web_events GROUP BY session_id) SELECT s.id, s.started_at, s.device, ss.max_duration_sec, ss.duration_sec_count FROM sessions s INNER JOIN session_stats ss ON s.id = ss.session_id WHERE ss.max_duration_sec >= 160 ORDER BY s.id DESC, max_duration_sec DESC;
